app.source:
{
  "format": "evidence-review/1",
  "module": {
    "id": "reading-attention-evidence",
    "version": "1.0.0",
    "title": "Understand reading and attention findings",
    "description": "Review a bounded fictional record before turning poor grades into an either-or explanation. Separate what has been professionally recorded from what remains unassessed.",
    "question": "What do the current assessment records establish about this child’s reading and attention difficulties, and what still needs assessment?",
    "boundary": "A fictional record-review example, not a diagnostic instrument. The finite catalogue describes possible professionally recorded reading and attention assessment conclusions, including coexistence and uncharacterized concerns. It is not an exhaustive catalogue of causes of poor grades. Only explicitly accepted, current records for the declared child, assessment episode and context constrain those possibilities. Logical agreement does not authenticate a record, establish clinical validity, attribute the cause of grades, prescribe support or estimate diagnostic probabilities.",
    "parameters": [],
    "relations": [
      {
        "id": "expectedScope",
        "source": "basis",
        "columns": [
          {
            "id": "field",
            "type": "string"
          },
          {
            "id": "value",
            "type": "string"
          }
        ],
        "key": [
          "field"
        ]
      },
      {
        "id": "possibility",
        "source": "basis",
        "columns": [
          {
            "id": "id",
            "type": "string"
          },
          {
            "id": "label",
            "type": "string"
          },
          {
            "id": "reading",
            "type": "string"
          },
          {
            "id": "attention",
            "type": "string"
          }
        ],
        "key": [
          "id"
        ]
      },
      {
        "id": "assessmentDomain",
        "source": "basis",
        "columns": [
          {
            "id": "id",
            "type": "string"
          },
          {
            "id": "label",
            "type": "string"
          }
        ],
        "key": [
          "id"
        ]
      },
      {
        "id": "concern",
        "source": "evidence",
        "columns": [
          {
            "id": "id",
            "type": "string"
          },
          {
            "id": "domain",
            "type": "string"
          },
          {
            "id": "description",
            "type": "string"
          },
          {
            "id": "source",
            "type": "string"
          },
          {
            "id": "observedDay",
            "type": "integer"
          }
        ],
        "key": [
          "id"
        ]
      },
      {
        "id": "finding",
        "source": "evidence",
        "columns": [
          {
            "id": "id",
            "type": "string"
          },
          {
            "id": "domain",
            "type": "string",
            "references": {
              "relation": "assessmentDomain",
              "column": "id"
            }
          },
          {
            "id": "status",
            "type": "string"
          },
          {
            "id": "professional",
            "type": "string"
          },
          {
            "id": "source",
            "type": "string"
          },
          {
            "id": "observedDay",
            "type": "integer"
          },
          {
            "id": "currentStatus",
            "type": "string"
          },
          {
            "id": "accepted",
            "type": "boolean"
          }
        ],
        "key": [
          "id"
        ]
      },
      {
        "id": "recordScope",
        "source": "evidence",
        "columns": [
          {
            "id": "record",
            "type": "string",
            "references": {
              "relation": "finding",
              "column": "id"
            }
          },
          {
            "id": "field",
            "type": "string"
          },
          {
            "id": "value",
            "type": "string"
          }
        ],
        "key": [
          "record",
          "field"
        ]
      },
      {
        "id": "candidate",
        "source": "assignment",
        "columns": [
          {
            "id": "id",
            "type": "string"
          }
        ]
      },
      {
        "id": "wrongScope",
        "source": "derived",
        "columns": [
          {
            "id": "record",
            "type": "string"
          }
        ]
      },
      {
        "id": "usableFinding",
        "source": "derived",
        "columns": [
          {
            "id": "record",
            "type": "string"
          },
          {
            "id": "domain",
            "type": "string"
          },
          {
            "id": "status",
            "type": "string"
          },
          {
            "id": "professional",
            "type": "string"
          },
          {
            "id": "source",
            "type": "string"
          }
        ]
      },
      {
        "id": "selectedProfile",
        "source": "derived",
        "columns": [
          {
            "id": "id",
            "type": "string"
          },
          {
            "id": "label",
            "type": "string"
          },
          {
            "id": "reading",
            "type": "string"
          },
          {
            "id": "attention",
            "type": "string"
          }
        ]
      },
      {
        "id": "conclusion",
        "source": "derived",
        "columns": [
          {
            "id": "domain",
            "type": "string"
          },
          {
            "id": "status",
            "type": "string"
          }
        ]
      },
      {
        "id": "supportedConclusion",
        "source": "derived",
        "columns": [
          {
            "id": "domain",
            "type": "string"
          },
          {
            "id": "label",
            "type": "string"
          }
        ]
      },
      {
        "id": "assessmentBoundary",
        "source": "derived",
        "columns": [
          {
            "id": "id",
            "type": "string"
          },
          {
            "id": "question",
            "type": "string"
          },
          {
            "id": "status",
            "type": "string"
          },
          {
            "id": "explanation",
            "type": "string"
          }
        ]
      },
      {
        "id": "recordDisposition",
        "source": "derived",
        "columns": [
          {
            "id": "record",
            "type": "string"
          },
          {
            "id": "domain",
            "type": "string"
          },
          {
            "id": "status",
            "type": "string"
          },
          {
            "id": "currentStatus",
            "type": "string"
          },
          {
            "id": "disposition",
            "type": "string"
          },
          {
            "id": "reason",
            "type": "string"
          },
          {
            "id": "source",
            "type": "string"
          },
          {
            "id": "professional",
            "type": "string"
          }
        ]
      }
    ],
    "generation": [
      {
        "id": "recorded-conclusion-combinations",
        "relation": "candidate",
        "from": {
          "relation": "possibility",
          "column": "id"
        },
        "min": 1,
        "max": 1,
        "label": "One bounded possibility about professionally recorded conclusions"
      }
    ],
    "rules": [
      {
        "id": "SCOPE.MISSING.OR.DIFFERENT",
        "label": "A finding must match every declared child, episode and context field",
        "head": {
          "relation": "wrongScope",
          "args": [
            "?record"
          ]
        },
        "body": [
          {
            "relation": "finding",
            "args": [
              "?record",
              "?domain",
              "?status",
              "?professional",
              "?source",
              "?observed",
              "?current",
              "?accepted"
            ]
          },
          {
            "relation": "expectedScope",
            "args": [
              "?field",
              "?expected"
            ]
          },
          {
            "op": "notExists",
            "atom": {
              "relation": "recordScope",
              "args": [
                "?record",
                "?field",
                "?expected"
              ]
            }
          }
        ]
      },
      {
        "id": "FINDING.USABLE",
        "label": "Only an explicitly accepted, current, in-scope professional record is used",
        "head": {
          "relation": "usableFinding",
          "args": [
            "?record",
            "?domain",
            "?status",
            "?professional",
            "?source"
          ]
        },
        "body": [
          {
            "relation": "finding",
            "args": [
              "?record",
              "?domain",
              "?status",
              "?professional",
              "?source",
              "?observed",
              "current",
              true
            ]
          },
          {
            "not": {
              "relation": "wrongScope",
              "args": [
                "?record"
              ]
            }
          }
        ]
      },
      {
        "id": "PROFILE.SELECTED",
        "label": "Interpret one declared combination of professionally recorded conclusions",
        "head": {
          "relation": "selectedProfile",
          "args": [
            "?profile",
            "?label",
            "?reading",
            "?attention"
          ]
        },
        "body": [
          {
            "relation": "candidate",
            "args": [
              "?profile"
            ]
          },
          {
            "relation": "possibility",
            "args": [
              "?profile",
              "?label",
              "?reading",
              "?attention"
            ]
          }
        ]
      },
      {
        "id": "READING.CONCLUSION",
        "label": "The selected interpretation supplies its reading conclusion",
        "head": {
          "relation": "conclusion",
          "args": [
            "reading-condition",
            "?reading"
          ]
        },
        "body": [
          {
            "relation": "selectedProfile",
            "args": [
              "?profile",
              "?label",
              "?reading",
              "?attention"
            ]
          }
        ]
      },
      {
        "id": "ATTENTION.CONCLUSION",
        "label": "The selected interpretation supplies its attention conclusion",
        "head": {
          "relation": "conclusion",
          "args": [
            "attention-condition",
            "?attention"
          ]
        },
        "body": [
          {
            "relation": "selectedProfile",
            "args": [
              "?profile",
              "?label",
              "?reading",
              "?attention"
            ]
          }
        ]
      },
      {
        "id": "SUPPORTED.CONCLUSION",
        "label": "A supported conclusion remains a recorded assessment finding, not a cause attribution",
        "head": {
          "relation": "supportedConclusion",
          "args": [
            "?domain",
            "?domainLabel"
          ]
        },
        "body": [
          {
            "relation": "conclusion",
            "args": [
              "?domain",
              "supported"
            ]
          },
          {
            "relation": "assessmentDomain",
            "args": [
              "?domain",
              "?domainLabel"
            ]
          }
        ]
      },
      {
        "id": "BOUNDARY.CAUSE",
        "label": "A reconciled professional conclusion does not explain the cause of grades",
        "head": {
          "relation": "assessmentBoundary",
          "args": [
            "cause-of-grades",
            "What explains the poor grades?",
            "not-assessed",
            "This review reconciles recorded conclusions; it does not establish whether either condition caused the grades or is their only explanation."
          ]
        },
        "body": [
          {
            "relation": "selectedProfile",
            "args": [
              "?profile",
              "?label",
              "?reading",
              "?attention"
            ]
          }
        ]
      },
      {
        "id": "BOUNDARY.OTHER.EXPLANATIONS",
        "label": "Other explanations stay outside this finite review regardless of the supported conclusions",
        "head": {
          "relation": "assessmentBoundary",
          "args": [
            "other-explanations",
            "Have other explanations been assessed or excluded?",
            "not-assessed",
            "Other or uncharacterized explanations remain unassessed by this model even when one or both professional conclusions are supported. The catalogue is deliberately nonexhaustive."
          ]
        },
        "body": [
          {
            "relation": "selectedProfile",
            "args": [
              "?profile",
              "?label",
              "?reading",
              "?attention"
            ]
          }
        ]
      },
      {
        "id": "DISPOSITION.WRONG.SCOPE",
        "label": "An out-of-scope record does not constrain this case",
        "head": {
          "relation": "recordDisposition",
          "args": [
            "?record",
            "?domain",
            "?status",
            "?current",
            "excluded",
            "The record does not match the declared child, assessment episode or context.",
            "?source",
            "?professional"
          ]
        },
        "body": [
          {
            "relation": "finding",
            "args": [
              "?record",
              "?domain",
              "?status",
              "?professional",
              "?source",
              "?observed",
              "?current",
              "?accepted"
            ]
          },
          {
            "relation": "wrongScope",
            "args": [
              "?record"
            ]
          }
        ]
      },
      {
        "id": "DISPOSITION.STALE",
        "label": "A record marked stale is retained but does not constrain the current conclusions",
        "head": {
          "relation": "recordDisposition",
          "args": [
            "?record",
            "?domain",
            "?status",
            "stale",
            "excluded",
            "A human record-applicability judgment marks this record stale; no medical expiry rule is inferred.",
            "?source",
            "?professional"
          ]
        },
        "body": [
          {
            "relation": "finding",
            "args": [
              "?record",
              "?domain",
              "?status",
              "?professional",
              "?source",
              "?observed",
              "stale",
              "?accepted"
            ]
          }
        ]
      },
      {
        "id": "DISPOSITION.CURRENCY.UNKNOWN",
        "label": "Unknown record currency remains an unresolved applicability question",
        "head": {
          "relation": "recordDisposition",
          "args": [
            "?record",
            "?domain",
            "?status",
            "unknown",
            "excluded",
            "Whether this record is current has not been established.",
            "?source",
            "?professional"
          ]
        },
        "body": [
          {
            "relation": "finding",
            "args": [
              "?record",
              "?domain",
              "?status",
              "?professional",
              "?source",
              "?observed",
              "unknown",
              "?accepted"
            ]
          }
        ]
      },
      {
        "id": "DISPOSITION.NOT.ACCEPTED",
        "label": "An unaccepted interpretation cannot constrain the record comparison",
        "head": {
          "relation": "recordDisposition",
          "args": [
            "?record",
            "?domain",
            "?status",
            "?current",
            "excluded",
            "The interpretation has not been explicitly accepted for this bounded comparison.",
            "?source",
            "?professional"
          ]
        },
        "body": [
          {
            "relation": "finding",
            "args": [
              "?record",
              "?domain",
              "?status",
              "?professional",
              "?source",
              "?observed",
              "?current",
              false
            ]
          }
        ]
      },
      {
        "id": "DISPOSITION.USED.supported",
        "label": "Use the recorded conclusion only in its own assessment domain",
        "head": {
          "relation": "recordDisposition",
          "args": [
            "?record",
            "?domain",
            "supported",
            "current",
            "used",
            "Accepted current in-scope professional record constrains only its own assessment domain.",
            "?source",
            "?professional"
          ]
        },
        "body": [
          {
            "relation": "usableFinding",
            "args": [
              "?record",
              "?domain",
              "supported",
              "?professional",
              "?source"
            ]
          }
        ]
      },
      {
        "id": "DISPOSITION.USED.not-supported",
        "label": "Use the recorded conclusion only in its own assessment domain",
        "head": {
          "relation": "recordDisposition",
          "args": [
            "?record",
            "?domain",
            "not-supported",
            "current",
            "used",
            "Accepted current in-scope professional record constrains only its own assessment domain.",
            "?source",
            "?professional"
          ]
        },
        "body": [
          {
            "relation": "usableFinding",
            "args": [
              "?record",
              "?domain",
              "not-supported",
              "?professional",
              "?source"
            ]
          }
        ]
      },
      {
        "id": "DISPOSITION.OPEN.not-assessed",
        "label": "An unassessed or unknown conclusion is not a negative finding",
        "head": {
          "relation": "recordDisposition",
          "args": [
            "?record",
            "?domain",
            "not-assessed",
            "current",
            "context-only",
            "The record leaves this domain unassessed or unknown; it excludes no possibility.",
            "?source",
            "?professional"
          ]
        },
        "body": [
          {
            "relation": "usableFinding",
            "args": [
              "?record",
              "?domain",
              "not-assessed",
              "?professional",
              "?source"
            ]
          }
        ]
      },
      {
        "id": "DISPOSITION.OPEN.unknown",
        "label": "An unassessed or unknown conclusion is not a negative finding",
        "head": {
          "relation": "recordDisposition",
          "args": [
            "?record",
            "?domain",
            "unknown",
            "current",
            "context-only",
            "The record leaves this domain unassessed or unknown; it excludes no possibility.",
            "?source",
            "?professional"
          ]
        },
        "body": [
          {
            "relation": "usableFinding",
            "args": [
              "?record",
              "?domain",
              "unknown",
              "?professional",
              "?source"
            ]
          }
        ]
      }
    ],
    "constraints": [
      {
        "id": "reading-condition.supported",
        "label": "An accepted reading-condition record stating supported must agree with that domain in the interpretation",
        "when": [
          {
            "relation": "usableFinding",
            "args": [
              "?record",
              "reading-condition",
              "supported",
              "?professional",
              "?source"
            ]
          },
          {
            "relation": "conclusion",
            "args": [
              "reading-condition",
              "?conclusion"
            ]
          }
        ],
        "assert": {
          "op": "eq",
          "args": [
            "?conclusion",
            "supported"
          ]
        }
      },
      {
        "id": "reading-condition.not-supported",
        "label": "An accepted reading-condition record stating not-supported must agree with that domain in the interpretation",
        "when": [
          {
            "relation": "usableFinding",
            "args": [
              "?record",
              "reading-condition",
              "not-supported",
              "?professional",
              "?source"
            ]
          },
          {
            "relation": "conclusion",
            "args": [
              "reading-condition",
              "?conclusion"
            ]
          }
        ],
        "assert": {
          "op": "eq",
          "args": [
            "?conclusion",
            "not-supported"
          ]
        }
      },
      {
        "id": "attention-condition.supported",
        "label": "An accepted attention-condition record stating supported must agree with that domain in the interpretation",
        "when": [
          {
            "relation": "usableFinding",
            "args": [
              "?record",
              "attention-condition",
              "supported",
              "?professional",
              "?source"
            ]
          },
          {
            "relation": "conclusion",
            "args": [
              "attention-condition",
              "?conclusion"
            ]
          }
        ],
        "assert": {
          "op": "eq",
          "args": [
            "?conclusion",
            "supported"
          ]
        }
      },
      {
        "id": "attention-condition.not-supported",
        "label": "An accepted attention-condition record stating not-supported must agree with that domain in the interpretation",
        "when": [
          {
            "relation": "usableFinding",
            "args": [
              "?record",
              "attention-condition",
              "not-supported",
              "?professional",
              "?source"
            ]
          },
          {
            "relation": "conclusion",
            "args": [
              "attention-condition",
              "?conclusion"
            ]
          }
        ],
        "assert": {
          "op": "eq",
          "args": [
            "?conclusion",
            "not-supported"
          ]
        }
      }
    ],
    "admission": [
      {
        "id": "PROFILE.COUNT",
        "label": "The authored catalogue contains exactly five bounded possibilities",
        "when": [
          {
            "count": {
              "relation": "possibility",
              "args": [
                "?profile",
                "?label",
                "?reading",
                "?attention"
              ]
            },
            "as": "?count"
          }
        ],
        "assert": {
          "op": "eq",
          "args": [
            "?count",
            5
          ]
        }
      },
      {
        "id": "PROFILE.reading-supported",
        "label": "The authored possibility catalogue cannot be silently changed by case data",
        "when": [],
        "assert": {
          "op": "exists",
          "atom": {
            "relation": "possibility",
            "args": [
              "reading-supported",
              "Reading conclusion supported; attention conclusion not supported",
              "supported",
              "not-supported"
            ]
          }
        }
      },
      {
        "id": "PROFILE.attention-supported",
        "label": "The authored possibility catalogue cannot be silently changed by case data",
        "when": [],
        "assert": {
          "op": "exists",
          "atom": {
            "relation": "possibility",
            "args": [
              "attention-supported",
              "Attention conclusion supported; reading conclusion not supported",
              "not-supported",
              "supported"
            ]
          }
        }
      },
      {
        "id": "PROFILE.coexisting-findings",
        "label": "The authored possibility catalogue cannot be silently changed by case data",
        "when": [],
        "assert": {
          "op": "exists",
          "atom": {
            "relation": "possibility",
            "args": [
              "coexisting-findings",
              "Reading and attention conclusions both supported",
              "supported",
              "supported"
            ]
          }
        }
      },
      {
        "id": "PROFILE.neither-supported",
        "label": "The authored possibility catalogue cannot be silently changed by case data",
        "when": [],
        "assert": {
          "op": "exists",
          "atom": {
            "relation": "possibility",
            "args": [
              "neither-supported",
              "Neither conclusion supported in the two reviewed domains; other explanations remain open",
              "not-supported",
              "not-supported"
            ]
          }
        }
      },
      {
        "id": "PROFILE.uncharacterized",
        "label": "The authored possibility catalogue cannot be silently changed by case data",
        "when": [],
        "assert": {
          "op": "exists",
          "atom": {
            "relation": "possibility",
            "args": [
              "uncharacterized",
              "Reading and attention concerns remain uncharacterized in this bounded catalogue",
              "uncharacterized",
              "uncharacterized"
            ]
          }
        }
      },
      {
        "id": "DOMAIN.COUNT",
        "label": "Exactly the two authored assessment domains are reviewed",
        "when": [
          {
            "count": {
              "relation": "assessmentDomain",
              "args": [
                "?domain",
                "?domainLabel"
              ]
            },
            "as": "?count"
          }
        ],
        "assert": {
          "op": "eq",
          "args": [
            "?count",
            2
          ]
        }
      },
      {
        "id": "DOMAIN.reading-condition",
        "label": "Assessment domain identity and meaning stay fixed",
        "when": [],
        "assert": {
          "op": "exists",
          "atom": {
            "relation": "assessmentDomain",
            "args": [
              "reading-condition",
              "Professionally recorded dyslexia assessment conclusion"
            ]
          }
        }
      },
      {
        "id": "DOMAIN.attention-condition",
        "label": "Assessment domain identity and meaning stay fixed",
        "when": [],
        "assert": {
          "op": "exists",
          "atom": {
            "relation": "assessmentDomain",
            "args": [
              "attention-condition",
              "Professionally recorded ADHD assessment conclusion"
            ]
          }
        }
      },
      {
        "id": "SCOPE.COUNT",
        "label": "Declare the exact child, assessment episode and context",
        "when": [
          {
            "count": {
              "relation": "expectedScope",
              "args": [
                "?field",
                "?value"
              ]
            },
            "as": "?count"
          }
        ],
        "assert": {
          "op": "eq",
          "args": [
            "?count",
            3
          ]
        }
      },
      {
        "id": "SCOPE.childId",
        "label": "Every authored scope dimension needs an explicit value",
        "when": [],
        "assert": {
          "op": "exists",
          "atom": {
            "relation": "expectedScope",
            "args": [
              "childId",
              "?value"
            ]
          }
        }
      },
      {
        "id": "SCOPE.assessmentEpisode",
        "label": "Every authored scope dimension needs an explicit value",
